preorder.implementation:
def preorder(root):
    if root:
        visit(root)
        preorder(root.left)
        preorder(root.right)

inorder.implementation:
def inorder(root):
    if root:
        inorder(root.left)
        visit(root)
        inorder(root.right)

postorder.implementation:
def postorder(root):
    if root:
        postorder(root.left)
        postorder(root.right)
        visit(root)

level_order.implementation:
def level_order(root):
    if not root:
        return
    queue = [root]
    while queue:
        node = queue.pop(0)
        visit(node)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

