def iterative_traversal(root):
    if not root:
        return

    stack = [root]

    while stack:
        node = stack.pop()
        visit(node)

        # Add children (right first for left-to-right processing)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
